import { Injectable, Logger, OnModuleDestroy } from '@nestjs/common';

import { PrismaClient } from '../prisma-client';
import { EmpresaContextService } from '../auth/empresa-context.service';

/**
 * Per-schema PrismaClient factory for PUB tenant isolation (D-619).
 *
 * `SET search_path` at query level is silently ignored by the Prisma Client:
 * each query generated by Prisma is fully qualified with the schema embedded in
 * `DATABASE_URL` (`?schema=...`) at connection time — confirmed with
 * `log:['query']` (the generated SQL always uses `"<schema-from-url>"."<table>"`,
 * never the value passed to `SET search_path`). This is a known Prisma limitation
 * without the `multiSchema` preview feature, which requires every tenant schema
 * declared statically in `schema.prisma` — incompatible with the runtime tenant
 * provisioning flow in ADR-003 (Saga onboarding creates `emp_<slug>` on demand).
 *
 * Solution (ADR-003-multi-tenancy.md §Resolution): one `PrismaClient` per schema,
 * each with its own `datasourceUrl` (`?schema=emp_<slug>`), cached by schema name.
 * Safe because tenants are pre-registered units of the same economic group — the
 * cache grows only to the number of empresas, not to the number of users or requests.
 *
 * The current empresa slug is read from `EmpresaContextService` (AsyncLocalStorage
 * populated by `EmpresaContextMiddleware` per HTTP request, or by
 * `GeneratePublicationUseCase.runAs` inside async build jobs — see INT-PUB-006).
 *
 * RULE-07: no PUB data access bypasses this service.
 *
 * Usage (repositories):
 * ```ts
 * await this.empresaService.withCurrentTenant(async (client) => {
 *   return client.publicacao.findMany({ where: { projetoId } });
 * });
 * ```
 *
 * @see docs/architecture/shared/multi-empresa.md
 * @see docs/architecture/backend/adr/ADR-003-multi-tenancy.md
 */
@Injectable()
export class PrismaEmpresaService implements OnModuleDestroy {
  private readonly logger = new Logger(PrismaEmpresaService.name);

  /** Cached per-schema Prisma clients. Keys are full schema names (`emp_aetos`). */
  private readonly clientsBySchema = new Map<string, PrismaClient>();

  constructor(private readonly empresaContext: EmpresaContextService) {}

  // ---------------------------------------------------------------------------
  // Instance API (used by repositories)
  // ---------------------------------------------------------------------------

  /**
   * Executes `fn` with a PrismaClient scoped to the current empresa schema.
   *
   * Reads the empresaId from the AsyncLocalStorage set by `EmpresaContextMiddleware`.
   * Throws when called outside a request or job context (context not set).
   *
   * The callback receives a `PrismaClient` directly (not a transaction proxy) so
   * repositories can open their own `$transaction` when atomicity is needed
   * (RULE-03: transactions are opened in the application service or in the adapter
   * when atomicity is local to the adapter).
   */
  async withCurrentTenant<T>(fn: (client: PrismaClient) => Promise<T>): Promise<T> {
    const { empresaId } = this.empresaContext.require();
    return this.withSlug(empresaId, fn);
  }

  /**
   * Executes `fn` with a PrismaClient scoped to the given empresaId.
   *
   * Normalizes defensively: strips the `emp_` prefix if the JWT claim already
   * includes it (proj-service convention, D-619). Schema becomes `emp_<slug>`.
   *
   * Used by tests via `empresaContext.runAs('aetos', () => repo.save(...))`, and
   * directly by the application service when propagating context to async build jobs
   * (INT-PUB-006).
   *
   * @param empresaId Slug (e.g. `"aetos"`) or prefixed slug (e.g. `"emp_aetos"`)
   * @param fn        Block of Prisma operations to run in the empresa schema
   */
  async withSlug<T>(empresaId: string, fn: (client: PrismaClient) => Promise<T>): Promise<T> {
    const slug = empresaId.replace(/^emp_/, '');
    PrismaEmpresaService.validateSlug(slug);
    const schema = `emp_${slug}`;
    const client = this.clientForSchema(schema);
    return fn(client);
  }

  // ---------------------------------------------------------------------------
  // Private helpers
  // ---------------------------------------------------------------------------

  /** Returns the cached PrismaClient for the schema, creating it on first access. */
  private clientForSchema(schema: string): PrismaClient {
    let client = this.clientsBySchema.get(schema);
    if (!client) {
      this.logger.log(`Opening PrismaClient for schema ${schema}`);
      client = new PrismaClient({ datasourceUrl: this.buildSchemaUrl(schema) });
      this.clientsBySchema.set(schema, client);
    }
    return client;
  }

  /**
   * Rewrites `DATABASE_URL` with `?schema=<schema>` to target the tenant schema.
   *
   * Prisma reads `datasourceUrl` at client construction — the schema param is
   * wired into every query at the client level, not per-query (D-619).
   */
  private buildSchemaUrl(schema: string): string {
    const base = process.env['DATABASE_URL'];
    if (!base) {
      throw new Error('DATABASE_URL environment variable is not set');
    }
    const url = new URL(base);
    url.searchParams.set('schema', schema);
    return url.toString();
  }

  /**
   * Validates the empresa slug before interpolating into a schema name.
   *
   * Pattern: `[a-z][a-z0-9_]{1,30}` — starts with a lowercase letter, then
   * lowercase alphanumeric + underscore, total 2–31 chars.
   * An invalid slug throws immediately — never silently falls back to any default schema.
   */
  private static validateSlug(slug: string): void {
    if (!/^[a-z][a-z0-9_]{1,30}$/.test(slug)) {
      throw new Error(
        `PrismaEmpresaService: invalid empresa slug "${slug}". ` +
          'Slug must match [a-z][a-z0-9_]{1,30}.',
      );
    }
  }

  /** Closes every cached per-schema connection pool on Nest module shutdown. */
  async onModuleDestroy(): Promise<void> {
    await Promise.all(
      Array.from(this.clientsBySchema.values()).map((client) => client.$disconnect()),
    );
    this.logger.log('All tenant PrismaClients disconnected');
  }
}
